#!/usr/bin/env python3
"""Create a self-contained, bounded-DOM audit with every funded order available for export."""
import gzip, json, sys
from pathlib import Path
root=Path(sys.argv[1] if len(sys.argv)>1 else 'docs/main-processing-audit-20261029')
data=json.loads((root/'summary.json').read_text())
with gzip.open(root/'orders.jsonl.gz','rt') as f: data['orders']=[json.loads(line) for line in f if line.strip()]
# Keep full per-context evidence in the downloadable JSON, not duplicated in the browser table.
for cfg in data['audit']['configs']:
    cfg['initial']={k:v for k,v in cfg['initial'].items() if k in ['ok','fail','n','gp','gl','measuredPf']}
data['audit'].pop('total',None)
encoded=json.dumps(data,separators=(',',':'),ensure_ascii=False).replace('<','\\u003c')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CTS-A-O · Main processing audit</title>
<style>
:root{font:15px/1.5 system-ui,sans-serif;color:#172c37;background:#f4f6f6}body{max-width:1480px;margin:auto;padding:28px}h1{font-size:30px;margin:6px 0}h2{margin:30px 0 10px;font-size:21px}h3{font-size:17px}p{max-width:1100px}.eyebrow{letter-spacing:.12em;font-size:12px;color:#46616d}.muted,small{color:#526871}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.card,section{background:white;border:1px solid #d6dfe3;padding:16px;border-radius:8px}.card b{font-size:29px;display:block;line-height:1.2}.warning{border-left:4px solid #b33535;background:#fff0ec;padding:14px}.good{color:#13683f}.bad{color:#9e2828}.scroll{overflow:auto;max-height:680px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:right;padding:8px 10px;border-bottom:1px solid #dee5e8;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{position:sticky;top:0;background:#edf2f3;color:#243d49;z-index:1}td.id{font:11px/1.4 ui-monospace,monospace;max-width:430px;white-space:normal;overflow-wrap:anywhere;text-align:left}td.dim{background:#f3f5f5;color:#687d86}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:12px 0}input,select,button{font:inherit;padding:8px;border:1px solid #a6bac3;border-radius:5px;background:white;color:inherit}input{min-width:250px;max-width:100%}button{cursor:pointer}button:disabled{opacity:.4;cursor:default}.pager{display:flex;gap:12px;align-items:center;margin:10px 0}.facts{display:grid;gap:7px}code{font:12px ui-monospace,monospace;overflow-wrap:anywhere}a{color:#1d5f80}@media(max-width:600px){body{padding:14px}h1{font-size:24px}.card b{font-size:24px}}@media print{body{max-width:none;background:white}.controls,.pager{display:none}.scroll{max-height:none}th{position:static}}
</style>
<div class="eyebrow">CTS-A-O · REPRODUCIBLE OFFLINE AUDIT · 29 OCTOBER 2026</div><h1>Main PF: validation, execution and close reasons</h1>
<p>Eight fixed symbols. <strong>7–8 October: 24h evaluated prehistory. 8–9 October: 24h trading.</strong> An additional 24h initializes indicators only. All used market data fits within 72 hours. This is a bounded diagnostic parameter grid, not a full factory-grid pass or exchange execution.</p>
<div class="warning"><strong>Trading performance remains poor.</strong> The report fixes do not improve returns. The repeated run retains every funded close, open holding, allocation and loss. A passing historical PF cannot guarantee the PF of later trades. The persistent Base → own Main → own Real → Active adapter is still pending integration in draft #219.</div>
<h2>Measured cohorts</h2><div id="kpis" class="grid"></div><p id="counts" class="muted"></p>
<section><h3>Confirmed reporting repairs</h3><ol><li>Validation uses an equal-weight mean of independently passing sets. No-loss sets are counted separately; the engine's finite no-loss gate score is never averaged as a measured PF.</li><li>Closed execution PF uses closed orders only. Open holdings retain their own mark-inclusive statistics and counts.</li><li>Lane, range, type and filtered listings use the same per-set accounting. Missing legacy mean evidence stays unavailable.</li></ol><p><strong>What remains:</strong> current production validation still reads candidate-tape histories. It does not yet evaluate each subsequent gate from a newly simulated, independently owned predecessor-stage set. This reporting release does not claim that architectural work is complete.</p></section>
<h2>Independent audit findings</h2><div id="findings" class="facts"></div>
<h2>Hourly executed PF heatmap</h2><p class="muted">Funded closed model orders only. Green: PF ≥1; red: PF &lt;1. Empty cells are unavailable. NL means positive gains with no losses. Colors do not substitute for the configured range gates.</p><div class="scroll"><table id="heat"></table></div>
<h2>Every strategy and range</h2><div class="scroll"><table id="types"></table></div>
<h2>Close reasons and hold times</h2><div class="scroll"><table id="exits"></table></div>
<h2>Every calculated config set and its later execution</h2><p class="muted">Complete independent config identities, including rejected and never selected candidates. Their PF does not enter the passing-set headline. Historical PF and later PF use different observation windows. All records are in this file; the table renders 100 at a time.</p><div class="controls"><input id="configQuery" type="search" aria-label="Search config sets" placeholder="Search all calculated configs"><select id="configState" aria-label="Filter config selection"><option value="">All configs</option><option value="selected">Initially selected</option><option value="unselected">Initially unselected</option></select></div><div class="pager"><button id="configPrev">Previous</button><span id="configPage" aria-live="polite"></span><button id="configNext">Next</button></div><div class="scroll"><table id="configs"></table></div>
<h2>Every funded order · line by line</h2><p class="muted">All orders remain in this file. The table renders 100 at a time to keep memory and scrolling bounded. Exports contain all columns and every row, including losing trades.</p><div class="controls"><input id="query" type="search" aria-label="Search orders by full config, symbol or close reason" placeholder="Config, symbol or close reason"><select id="kind" aria-label="Filter strategy"><option value="">All strategies</option></select><button id="jsonl">Export complete order JSONL</button><button id="csv">Export complete order CSV</button></div><div class="pager"><button id="prev">Previous</button><span id="page" aria-live="polite"></span><button id="next">Next</button></div><div class="scroll"><table id="orders"></table></div>
<h2>Strategy switches and adjustments</h2><p class="muted">The baseline run performed 114 walk-forward controls on the same tapes, one setting changed per case. These are diagnostic controls on the same historical window, not unseen profitability evidence. Cases requiring new tapes remain uncomputed. The repeat disables these already-recorded controls to reduce time and memory.</p><div class="scroll"><table id="variants"></table></div>
<h2>Coverage and reproducibility</h2><div id="coverage" class="facts"></div><p><a href="summary.json">Detailed summary JSON</a> · <a href="protocol.json">Frozen protocol</a> · <a href="orders.jsonl.gz">Compressed complete order listing</a> · <a href="evidence.tar.gz">Raw evidence and checksummed sidecars</a></p><details><summary>Exact source, feed and order checksums</summary><pre id="hashes" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre></details>
<script id="audit-data" type="application/json">__DATA__</script>
<script>
'use strict';const D=JSON.parse(document.getElementById('audit-data').textContent),A=D.audit,O=D.orders;
const el=(name,text)=>{const n=document.createElement(name);if(text!==undefined)n.textContent=text;return n};
const fmt=(n,d=4)=>typeof n==='number'&&Number.isFinite(n)?n.toFixed(d):'Unavailable';
const pct=n=>fmt(n*100,2)+'%';const when=t=>new Date(t).toISOString().slice(5,16).replace('T',' ');
const pf=s=>!s||!s.n?'—':s.noLoss?'NL':fmt(s.pf,4);
function table(id,heads,rows){const t=document.getElementById(id);t.replaceChildren();const tr=el('tr');heads.forEach(x=>tr.append(el('th',x)));const h=el('thead');h.append(tr);t.append(h);const b=el('tbody');for(const row of rows){const r=el('tr');for(let i=0;i<row.length;i++){const v=row[i],c=el('td',v&&typeof v==='object'?v.text:v);if(i===0&&String(c.textContent).length>65)c.className='id';if(v&&typeof v==='object'&&v.color)c.style.background=v.color;r.append(c)}b.append(r)}t.append(b)}
const cards=[['Base passing pairs',D.baseCounts.basePassed+' / '+D.baseCounts.baseEvaluated,pct(D.baseCounts.basePassed/D.baseCounts.baseEvaluated)+' · includes independent Exit Base'],['Initial config validation',D.initialValidation.passed+' / '+D.initialValidation.evaluated,pct(D.initialValidation.passed/D.initialValidation.evaluated)],['Historical passing-set mean',fmt(A.initialSelection.finiteMeanPf),A.initialSelection.finiteSets+' finite sets + '+A.initialSelection.noLossSets+' no-loss'],['Later executed PF',fmt(D.parity.execution.pf),D.parity.matched+' exact funded closes'],['Exact cohort matches',D.parity.matched+' / '+D.parity.totalExecutions,D.parity.mismatchCount+' changed returns; '+D.parity.missingCount+' missing'],['Repeat time / peak RSS',fmt(D.resources.wallSeconds,2)+' s',fmt(D.resources.peakRssKiB/1024,1)+' MiB · controls disabled']];
for(const [label,value,sub]of cards){const c=el('div');c.className='card';c.append(el('small',label),el('b',value),el('small',sub));document.getElementById('kpis').append(c)}
const C=A.counts;document.getElementById('counts').textContent='Funded model positions opened / closed / held: '+[C.openedPositions,C.closedPositions,C.openPositions].join(' / ')+' · orders: '+[C.openedOrders,C.settledOrders,C.openOrders].join(' / ')+'. Venue and funded exchange PF: unavailable.';
const findings=[A.entryChecks+' exact funded entries rechecked against Base permission, config, own direction and configured symbol gate: '+A.issues.length+' failures.',A.ordinaryCostChecked+' Normal/Trailing cost checks: one 0.15% round trip; largest compact-price return error '+A.maxCostError.toExponential(3)+'. DCA/Axis intrinsic ladder returns are not treated as simple price returns.',A.sourceOwnConfigReadiness.contextClosesBelow9+' entries had fewer than 9 historical closes on their own symbol/direction. Minimum own-direction pooled count: '+A.sourceOwnConfigReadiness.minimumDirectionCloses+'; minimum symbol/direction count: '+A.sourceOwnConfigReadiness.minimumContextCloses+'. These are different configured evidence scopes.',D.comparison.exactFundedTradeRecords&&D.comparison.exactHeldRecords&&D.comparison.exactAllocations?'Before / after: every funded trade, held order and allocation is identical. No losing fill was removed.':'Before / after comparison incomplete.','Normal TP closes are present. Wider SL losses, trailing closes near breakeven after cost and 8h/16h timed exits all contribute to the observed loss. The 15min Micro lane produced no funded close in this session; its TP/expiry behavior is covered by separate deterministic 72h regressions.'];
findings.forEach(x=>document.getElementById('findings').append(el('div',x)));
const kinds=['normal','trailing','trailing-only','dca','dca-active','axis','exit'];
const sums=xs=>{let gp=0,gl=0;for(const x of xs){gp+=Math.max(0,x.unitReturn??0);gl+=Math.max(0,-(x.unitReturn??0))}return{n:xs.length,pf:xs.length&&gl?gp/gl:null,noLoss:xs.length>0&&gp>0&&gl===0}};
const tint=s=>!s.n?'#f1f4f4':s.noLoss||s.pf>=1?'#dff0e6':'#f9e2de';
const hours=Array.from({length:24},(_,i)=>A.window.startT+i*3600000);table('heat',['Settled UTC',...kinds],hours.map(t=>[when(t),...kinds.map(k=>{const s=sums(O.filter(x=>x.kind===k&&x.exitT>t&&x.exitT<=t+3600000));return{text:pf(s)+' · '+s.n,color:tint(s)}})]));
const ranges=['mc','mn','sh','gn','lg','wide','sig'];table('types',['Strategy',...ranges.map(x=>x+' PF · closes')],kinds.map(k=>[k,...ranges.map(r=>{const s=sums(O.filter(x=>x.kind===k&&x.range===r));return{text:pf(s)+' · '+s.n,color:tint(s)}})]));
const exitKeys=[...new Set(O.map(x=>x.kind+' | '+x.reason))].sort();table('exits',['Strategy | reason','Closes','PF','Avg hold min','Min hold','Max hold','Unit gains','Unit losses'],exitKeys.map(k=>{const xs=O.filter(x=>x.kind+' | '+x.reason===k),s=sums(xs),hs=xs.map(x=>x.holdMinutes);return[k,s.n,pf(s),fmt(hs.reduce((a,b)=>a+b,0)/hs.length,1),Math.min(...hs),Math.max(...hs),fmt(xs.reduce((a,x)=>a+Math.max(0,x.unitReturn),0)),fmt(xs.reduce((a,x)=>a+Math.max(0,-x.unitReturn),0))]}));
let configPage=0,configFiltered=A.configs;
function drawConfigs(){const max=Math.max(1,Math.ceil(configFiltered.length/100));configPage=Math.min(configPage,max-1);table('configs',['Complete config ID','Type','Range','Base allowed','Initial selected','Initial verdict','Initial closes','Historical PF','Later closes','Later PF'],configFiltered.slice(configPage*100,(configPage+1)*100).map(x=>[x.cfg,x.kind,x.range,x.initialBaseAllowed?'yes':'no',x.initiallySelected?'yes':'no',x.initial.ok?'qualified':x.initial.fail,x.initial.n,x.initial.gl===0&&x.initial.gp>0?'NL':fmt(x.initial.measuredPf),x.subsequent.n,pf(x.subsequent)]));document.getElementById('configPage').textContent='Page '+(configPage+1)+' / '+max+' · '+configFiltered.length+' configs';document.getElementById('configPrev').disabled=configPage===0;document.getElementById('configNext').disabled=configPage>=max-1}
function filterConfigs(){const q=document.getElementById('configQuery').value.trim().toLowerCase(),s=document.getElementById('configState').value;configFiltered=A.configs.filter(x=>(!q||x.cfg.toLowerCase().includes(q))&&(!s||(s==='selected')===x.initiallySelected));configPage=0;drawConfigs()}
document.getElementById('configQuery').addEventListener('input',filterConfigs);document.getElementById('configState').addEventListener('change',filterConfigs);document.getElementById('configPrev').onclick=()=>{configPage--;drawConfigs()};document.getElementById('configNext').onclick=()=>{configPage++;drawConfigs()};drawConfigs();
let page=0,filtered=O;for(const k of [...new Set(O.map(x=>x.kind))].sort()){const op=el('option',k);op.value=k;document.getElementById('kind').append(op)}
function drawOrders(){const max=Math.max(1,Math.ceil(filtered.length/100));page=Math.min(page,max-1);table('orders',['Config','Symbol','Side','Type','Entry UTC','Exit UTC','Hold min','Close reason','Unit return','External ×','Config N','Own-side N','Symbol/side N','Gate check'],filtered.slice(page*100,(page+1)*100).map(x=>[x.cfg,x.symbol,x.side===1?'long':'short',x.kind,when(x.entryT),when(x.exitT),x.holdMinutes,x.reason,pct(x.unitReturn),fmt(x.externalMultiplier,4),x.beforeEntryConfigN,x.beforeEntryDirectionN,x.beforeEntryContextN,x.failures.length?x.failures.join(','):'passed']));document.getElementById('page').textContent='Page '+(page+1)+' / '+max+' · '+filtered.length+' matching orders';document.getElementById('prev').disabled=page===0;document.getElementById('next').disabled=page>=max-1}
function filter(){const q=document.getElementById('query').value.trim().toLowerCase(),k=document.getElementById('kind').value;filtered=O.filter(x=>(!k||x.kind===k)&&(!q||(x.cfg+' '+x.symbol+' '+x.reason).toLowerCase().includes(q)));page=0;drawOrders()}
document.getElementById('query').addEventListener('input',filter);document.getElementById('kind').addEventListener('change',filter);document.getElementById('prev').onclick=()=>{page--;drawOrders()};document.getElementById('next').onclick=()=>{page++;drawOrders()};drawOrders();
function save(name,text,type){const a=el('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.getElementById('jsonl').onclick=()=>save('cts-ao-all-funded-orders.jsonl',O.map(x=>JSON.stringify(x)).join('\\n')+'\\n','application/x-ndjson');
document.getElementById('csv').onclick=()=>{const cols=Object.keys(O[0]),cell=v=>'"'+String(Array.isArray(v)?v.join(';'):v??'').replaceAll('"','""')+'"';save('cts-ao-all-funded-orders.csv',[cols,...O.map(x=>cols.map(k=>x[k]))].map(xs=>xs.map(cell).join(',')).join('\\n')+'\\n','text/csv')};
table('variants',['Control','Status','Orders','Unit PF','Sized net Σ %','Effect'],D.variants.rows.map(x=>[x.label,x.status,x.summary?.orders??'—',fmt(x.summary?.pf),fmt(x.summary?.net,2),x.effect??x.why??'—']));
const checks=D.checks.filter(x=>!x.ok);const coverage=['Report checks: '+(D.checks.length-checks.length)+' / '+D.checks.length+' pass. This is not a complete catalog pass.','30m Base startup had 96 historical bars, below the production minimum 120. With 24h trading and at most 72h total data, this lane cannot supply that startup history. No missing 30m sample is counted as validated.',...checks.map(x=>'Incomplete: '+x.name+' · expected '+x.expected+', observed '+x.actual),D.study.study.scope];coverage.forEach(x=>document.getElementById('coverage').append(el('div',x)));
document.getElementById('hashes').textContent=JSON.stringify({source:D.study.source,feed:D.study.feed,tradeSha256:D.comparison.tradeSha256,scope:D.audit.scope},null,2);
</script></html>'''
(root/'report.html').write_text(html.replace('__DATA__',encoded))
print(json.dumps({'file':str(root/'report.html'),'orders':len(data['orders']),'configs':len(data['audit']['configs']),'bytes':(root/'report.html').stat().st_size}))
